SELECT * FROM (SELECT x FROM t WHERE id > 2 UNION SELECT w FROM u WHERE tid < 5 ORDER BY 1 LIMIT 4 OFFSET 1) ORDER BY 1;
SELECT tv.id, tv.n, uv.mw FROM tv LEFT JOIN uv ON uv.tid = tv.id ORDER BY 1, 2, 3;
SELECT id, x FROM t ORDER BY id  LIMIT -1;
SELECT DISTINCT y, x % 2 FROM t ORDER BY 1 DESC, 2 DESC NULLS FIRST;
SELECT id, x FROM t ORDER BY (SELECT count(*) FROM u WHERE u.tid = t.id) DESC, x NULLS LAST, id;
SELECT id, x FROM t ORDER BY id  LIMIT (SELECT count(*) FROM u) / 2 OFFSET (SELECT min(id) FROM u);
